class Image:
    """File-backed allocated section mapping; NOBITS has no readable bytes."""
    def __init__(self, data):
        self.data = data
        require(len(data) >= 64 and data[:6] == b'\x7fELF\x02\x01', 'not ELF64 LE')
        require(struct.unpack_from('<HH', data, 16) == (3, 62), 'not x86-64 ET_DYN')
        self.sections = sections(data)
        names = [s['name'] for s in self.sections]
        require(len(names) == len(set(names)), 'duplicate section names')
        self.by_name = {s['name']: s for s in self.sections}

    def offset(self, va, size):
        require(isinstance(va, int) and isinstance(size, int) and va >= 0 and size > 0,
                'invalid address range')
        matches = [s for s in self.sections
                   if s['type'] != 8 and s['flags'] & 2 and s['address'] <= va
                   and va + size <= s['address'] + s['size']]
        require(len(matches) == 1, 'unmapped, ambiguous, or non-file-backed address')
        s = matches[0]
        offset = s['offset'] + va - s['address']
        require(offset + size <= len(self.data), 'range beyond file')
        return offset

    def read(self, va, size):
        off = self.offset(va, size)
        return bytes(self.data[off:off + size])

    def section(self, name):
        require(name in self.by_name, 'missing required section')
        s = self.by_name[name]
        require(s['type'] != 8 and s['size'] and s['flags'] & 2,
                'section is not file-backed allocated data')
        return s


def checked(image, va, expected_hex):
    expected = bytes.fromhex(expected_hex)
    actual = image.read(va, len(expected))
    require(actual == expected, f'fixed instruction or data mismatch at {va:#x}')
    return actual


def branch(image, site, expected_hex, expected_target):
    raw = checked(image, site, expected_hex)
    if len(raw) == 2 and 0x70 <= raw[0] <= 0x7f:
        condition, delta = raw[0] & 15, struct.unpack('<b', raw[1:])[0]
    elif len(raw) == 6 and raw[0] == 15 and 0x80 <= raw[1] <= 0x8f:
        condition, delta = raw[1] & 15, struct.unpack('<i', raw[2:])[0]
    else:
        raise EvidenceError('unsupported conditional branch')
    target = site + len(raw) + delta
    require(target == expected_target, 'branch destination mismatch')
    return condition, site + len(raw), target


def call(image, site, expected_hex, expected_target):
    raw = checked(image, site, expected_hex)
    require(len(raw) == 5 and raw[0] == 0xe8, 'not a direct rel32 call')
    target = site + 5 + struct.unpack('<i', raw[1:])[0]
    require(target == expected_target, 'call destination mismatch')
    return target


def selected_fdes(image):
    secs, index = unwind_index(image.data)
    _, fdes = eh_frame_records(image.data, secs)
    indexed = {row['start']: row for row in index}
    by_start = {}
    for f in fdes:
        if f['start'] in {x[0] for x in FDE_PINS}:
            require(f['start'] not in by_start, 'duplicate selected FDE start')
            by_start[f['start']] = f
    out = []
    for start, end, digest in FDE_PINS:
        f = by_start.get(start)
        require(f is not None and f['end'] == end, 'missing or changed FDE extent')
        entry = indexed.get(start)
        require(entry is not None and entry['fde'] == f['fde'], 'FDE index mismatch')
        code = image.read(start, end - start)
        require(hashlib.sha256(code).hexdigest() == digest, 'selected FDE body changed')
        out.append({**f, 'index': entry['index'], 'raw': code.hex(),
                    'file_offset': image.offset(start, len(code)), 'sha256': digest})
    return out


def lsda_rows(image, fde):
    va = fde['lsda']
    if va is None:
        return None, []
    sec = image.section('.gcc_except_table')
    require(sec['address'] <= va < sec['address'] + sec['size'], 'LSDA outside section')
    base = image.offset(va, 1)
    end = sec['offset'] + sec['size']
    data = image.data
    pos = base
    require(pos + 2 <= end and data[pos] == 0xff, 'unsupported LSDA LPStart')
    pos += 1
    ttype = data[pos]
    pos += 1
    type_offset = None
    if ttype != 0xff:
        require(ttype == 0x9b, 'unsupported LSDA type encoding')
        type_offset, pos = uleb(data, pos, end)
        require(pos + type_offset <= end, 'LSDA type table outside section')
    require(pos < end and data[pos] == 1, 'unsupported call-site encoding')
    pos += 1
    size, pos = uleb(data, pos, end)
    stop = pos + size
    require(stop <= end, 'truncated LSDA call-site table')
    rows = []
    while pos < stop:
        raw_start = pos
        delta, pos = uleb(data, pos, stop)
        length, pos = uleb(data, pos, stop)
        landing, pos = uleb(data, pos, stop)
        action, pos = uleb(data, pos, stop)
        require(delta + length <= fde['end'] - fde['start'], 'LSDA range outside FDE')
        require(landing == 0 or landing < fde['end'] - fde['start'],
                'LSDA landing outside FDE')
        rows.append({'start': fde['start'] + delta, 'end': fde['start'] + delta + length,
                     'landing': fde['start'] + landing if landing else None,
                     'action': action, 'raw': bytes(data[raw_start:pos]).hex()})
    require(pos == stop, 'LSDA row overruns table')
    return {'address': va, 'offset': base, 'ttype': ttype, 'type_offset': type_offset,
            'header': bytes(data[base:stop - size]).hex(), 'table_size': size}, rows


def relative_relocations(image, requested):
    s = image.section('.rela.dyn')
    require(s['size'] % 24 == 0, 'invalid RELA section size')
    found = {a: [] for a in requested}
    for off in range(s['offset'], s['offset'] + s['size'], 24):
        target, info, addend = struct.unpack_from('<QQq', image.data, off)
        if target in found:
            found[target].append((off, info, addend))
    out = []
    for slot, expected in sorted(requested.items()):
        require(len(found[slot]) == 1, 'missing or duplicate selected relocation')
        off, info, addend = found[slot][0]
        require(info == 8 and addend == expected, 'relocation type, symbol or addend changed')
        out.append({'slot': slot, 'entry_offset': off, 'info': info, 'addend': addend,
                    'raw': bytes(image.data[off:off + 24]).hex()})
    return out


def rip_fragment(image, site, prefix_hex, size):
    prefix = bytes.fromhex(prefix_hex)
    raw = image.read(site, len(prefix) + 4)
    require(raw.startswith(prefix), 'wrong RIP-relative instruction')
    va = site + len(raw) + struct.unpack('<i', raw[-4:])[0]
    return va, image.read(va, size)


# Each short literal is reconstructed from the same overlapping words or SIMD
# blocks that the fixed comparison instructions read. Offsets are within a key.
KEY_SPECS = (
    ('outer', 0x31212b3, ((0x31212bf, '330d', 0, 4), (0x31212c8, '3305', 3, 4)),
     0x31212f0, 'tracker'),
    ('outer', 0x312129c, ((0x312134f, 'f30f6f0d', 0, 16),),
     0x312137c, 'quorum_l1_hashes'),
    ('outer', 0x312128d, ((0x31213cf, 'f30f6f05', 0, 16), (0x31213e4, 'f30f6f15', 5, 16)),
     0x31214b9, 'highest_quorum_height'),
    ('row', 0x3188ac4, ((0x3188ad0, '330d', 0, 4), (0x3188ad9, '3305', 3, 4)),
     0x3188aec, 'l1_hash'),
    ('row', 0x3188abe, ((0x3188b3f, 'f30f6f05', 0, 16), (0x3188b54, 'f30f6f15', 5, 16)),
     0x3188b76, 'hot_user_to_signature'),
    ('row', 0x3188aa2, ((0x3188bc9, 'f30f6f05', 0, 16), (0x3188bde, 'f30f6f15', 7, 16)),
     0x3188c9d, 'hard_voter_to_signature'),
)


def decode_keys(image):
    branch_by_site = {site: (raw, target) for site, raw, target in BRANCH_PINS}
    records = []
    for group, cmp_site, fragments, guard, expected_name in KEY_SPECS:
        cmp_raw = image.read(cmp_site, 4)
        require(cmp_raw[:3] == b'\x48\x83\xf9', 'unexpected key length comparison')
        length = cmp_raw[3]
        key = [None] * length
        pieces = []
        for site, prefix, offset, size in fragments:
            addr, data = rip_fragment(image, site, prefix, size)
            require(offset + size <= length, 'comparison outside key length')
            for i, value in enumerate(data):
                slot = offset + i
                require(key[slot] is None or key[slot] == value, 'inconsistent overlapping comparison')
                key[slot] = value
            pieces.append({'instruction': site, 'data_va': addr, 'offset': offset, 'bytes': data.hex()})
        require(all(x is not None for x in key), 'key comparison has a gap')
        raw_name = bytes(key)
        require(raw_name == expected_name.encode('ascii'), 'unexpected reconstructed key')
        raw_branch, expected = branch_by_site[guard]
        _, _, duplicate = branch(image, guard, raw_branch, expected)
        records.append({'group': group, 'name': expected_name, 'length': length,
                        'length_site': cmp_site, 'duplicate_guard': guard,
                        'duplicate_target': duplicate, 'pieces': pieces})
    return records


def classify(key, records):
    """Model only the exact length and overlapping comparisons recorded above."""
    require(isinstance(key, bytes), 'key must be bytes')
    for item in records:
        if len(key) != item['length']:
            continue
        if all(key[p['offset']:p['offset'] + len(bytes.fromhex(p['bytes']))] ==
               bytes.fromhex(p['bytes']) for p in item['pieces']):
            return item['name']
    return None


def tracker_dispatch(image):
    """Recover the tracker's key tags and its two map-dispatch tables."""
    for site, expected in (
        (0x300888f, '4883f901'), (0x3008895, '4883f903'),
        (0x300889b, '4883f904'), (0x30088ab, '31c9'),
        (0x30088cb, 'b101'), (0x30088cf, 'b102803869'),
        (0x30088d6, 'b103'), (0x300882b, 'c6430104'),
    ):
        checked(image, site, expected)
    _, name = rip_fragment(image, 0x30088a3, '3b05', 4)
    _, hsc_head = rip_fragment(image, 0x30088b2, '66330d', 2)
    _, hsc_tail = rip_fragment(image, 0x30088bd, '3205', 1)
    i_raw = image.read(0x30088d1, 3)
    names = [name.decode('ascii'), (hsc_head + hsc_tail).decode('ascii'),
             bytes([i_raw[2]]).decode('ascii')]
    require(names == ['name', 'hsc', 'i'], 'tracker key bytes changed')

    tables = []
    for site, prefix in ((0x31a11cc, '488d0d'), (0x31a178f, '4c8d25')):
        base, data = rip_fragment(image, site, prefix, 20)
        targets = [base + value for value in struct.unpack('<5i', data)]
        tables.append((base, data.hex(), targets))
    require(tables[0][2] == [0x31a11dc, 0x31a1238, 0x31a1591, 0x31a209b, 0x31a1607]
            and tables[1][2] == [0x31a1851, 0x31a18bb, 0x31a1c8f, 0x31a209b, 0x31a1cef],
            'tracker dispatch table changed')
    selected = {site: (raw, target) for site, raw, target in BRANCH_PINS}
    duplicates = ((0x31a11e1, 0x31a1856), (0x31a1241, 0x31a18c4))
    for first, second in duplicates:
        branch(image, first, *selected[first])
        branch(image, second, *selected[second])
    for site in (0x31a1619, 0x31a1d04, 0x31a1d0d):
        branch(image, site, *selected[site])
    require([selected[s][1] for s in (0x31a1619, 0x31a1d04, 0x31a1d0d)] ==
            [0x31a1d0a, 0x31a161f, 0x31a1d84], 'changed tracker completion order')
    # Once i has been parsed, its second dispatch entry goes directly to the
    # duplicate-i construction. The completion mask defaults absent hsc to zero.
    checked(image, 0x31a1d4d, 'f30f7e8424a0000000660f70c000660f72f01f'
                            '660f72e01f660fdb842450010000')
    rows = []
    for tag, name in enumerate(names):
        before = selected[duplicates[tag][0]][1] if tag < 2 else None
        after = selected[duplicates[tag][1]][1] if tag < 2 else tables[1][2][tag]
        rows.append((tag, name, tables[0][2][tag], tables[1][2][tag], before, after))
    return rows, tables


def tracker_presence_cases():
    # A model of the selected completion checks, not a JSON parser.
    rows = []
    for mask in range(8):
        name, hsc, present_i = (bool(mask & (1 << bit)) for bit in range(3))
        result = 'missing:name' if not name else 'missing:i' if not present_i else 'complete'
        policy = ('present_child_words' if hsc else 'two_zero_words') if result == 'complete' else ''
        rows.append((mask, result, policy))
    return rows


def hsc_dispatch(image):
    """Recover the two selected map keys, child calls, and error branches."""
    checked(image, 0x30e72f6, '48837c241801')
    i = checked(image, 0x30e7301, '83f869')[2]
    q = checked(image, 0x30e730a, '83f871')[2]
    require((q, i) == (ord('q'), ord('i')), 'changed hsc keys')
    q_store = checked(image, 0x30e75db, '4c897b08')
    i_store = checked(image, 0x30e75e5, 'f20f114310')
    offsets = (q_store[-1] - 8, i_store[-1] - 8)
    require(offsets == (0, 8), 'changed hsc payload offsets')
    selected = {site: (raw, target) for site, raw, target in BRANCH_PINS}
    rows = []
    for name, offset, child_site, duplicate_site, missing_site in (
        (chr(q), offsets[0], 0x30e7474, 0x30e7313, 0x30e759a),
        (chr(i), offsets[1], 0x30e74b2, 0x30e7406, 0x30e75a5),
    ):
        duplicate = branch(image, duplicate_site, *selected[duplicate_site])[2]
        missing = branch(image, missing_site, *selected[missing_site])[2]
        child = rel32_at(image, child_site)
        require(child == 0x3087600, 'changed hsc numeric child')
        rows.append((name, offset, child_site, child, duplicate_site, duplicate, missing_site, missing))
    return rows


def diagnostic_links(image):
    """Follow selected RIP-relative error-name references into file bytes."""
    specs = (
        ('tracker_missing', 0x31a161f, b'name'),
        ('tracker_missing', 0x31a1d84, b'i'),
        ('tracker_duplicate', 0x31a1efb, b'name'),
        ('tracker_duplicate', 0x31a1ea6, b'hsc'),
        ('tracker_duplicate', 0x31a1c9d, b'i'),
        ('hsc_missing', 0x30e76ac, b'q'),
        ('hsc_missing', 0x30e76b5, b'i'),
        ('hsc_duplicate', 0x30e77e2, b'q'),
        ('hsc_duplicate', 0x30e77eb, b'i'),
    )
    rows = []
    for role, site, expected in specs:
        address, literal = rip_fragment(image, site, '488d05', len(expected))
        require(literal == expected, 'changed diagnostic name')
        rows.append((role, site, address, literal.decode('ascii')))
    return rows


def diagnostic_templates(image):
    """Check the selected error format descriptors behind the named paths."""
    rows = []
    for role, site, expected in (
        ('tracker_missing_name', 0x31a164a, b'missing field `'),
        ('tracker_missing_i', 0x31a1daf, b'missing field `'),
        ('tracker_duplicate_name', 0x31a1f26, b'duplicate field `'),
        ('tracker_duplicate_hsc', 0x31a1ed1, b'duplicate field `'),
        ('tracker_duplicate_i', 0x31a1cce, b'duplicate field `'),
        ('hsc_missing', 0x30e76e0, b'missing field `'),
        ('hsc_duplicate', 0x30e7816, b'duplicate field `'),
    ):
        address, length = rip_fragment(image, site, '488d3d', 1)
        raw = image.read(address, 1 + length[0])
        require(raw == bytes([len(expected)]) + expected, 'changed diagnostic template')
        rows.append((role, site, address, raw.hex(), expected.decode('ascii')))
    return rows


def hsc_presence_cases():
    # q is checked before i on the selected map-completion path.
    return [(mask, 'missing:q' if not mask & 1 else 'missing:i' if not mask & 2 else 'complete')
            for mask in range(4)]


def named_literal(image, lea_site, length_site):
    raw = image.read(lea_site, 7)
    require(raw[:3] == b'\x48\x8d\x35', 'unexpected literal LEA')
    ptr = lea_site + 7 + struct.unpack('<i', raw[3:])[0]
    mov = image.read(length_site, 5)
    require(mov[0] == 0xba, 'unexpected literal length instruction')
    size = struct.unpack('<I', mov[1:])[0]
    require(0 < size < 100, 'invalid literal length')
    name = image.read(ptr, size)
    require(all(32 <= x < 127 for x in name), 'literal not printable ASCII')
    return ptr, name.decode('ascii')


def rel32_at(image, site):
    data = image.read(site, 5)
    require(data[0] == 0xe8, 'not a direct call')
    return site + 5 + struct.unpack('<i', data[1:])[0]


def writer_fields(image, keys):
    # The source displacements are decoded from already pinned instructions.
    specs = [
        ('low', 0x1e84dcc, 0x1e84dd3, 0x1e84df5, None),
        ('low', 0x1e84e11, 0x1e84e18, 0x1e84e37, (0x1e84e2b, '498d57')),
        ('low', 0x1e84e4e, 0x1e84e55, 0x1e84e73, (0x1e84e43, '4d8b7f')),
        ('shared', 0x48c8c1c, 0x48c8c23, 0x48c8c45, None),
        ('shared', 0x48c8c61, 0x48c8c68, 0x48c8c87, (0x48c8c7b, '498d57')),
        ('shared', 0x48c8c9e, 0x48c8ca5, 0x48c8cc3, (0x48c8c93, '4d8b7f')),
        ('json', 0x1e84f34, 0x1e84f3e, 0x1e84f86, None),
        ('json', 0x1e84f9d, 0x1e84fa7, 0x1e84fac, (0x1e84f99, '488d4b')),
        ('json', 0x1e84fc8, 0x1e84fd2, 0x1e84fda, (0x1e84fc4, '4883c3')),
        ('tracker', 0x2326f1f, 0x2326f26, 0x2326f46, (0x2326f10, '4d8b67')),
        ('tracker', 0x2326f58, 0x2326f5f, 0x2326f7c, (0x2326f72, '498d77')),
        ('tracker', 0x2326f92, 0x2326f99, 0x2326fb9, (0x2326fac, '4983c7')),
        ('value', 0x1e845b6, 0x1e845bd, 0x1e84610, None),
        ('value', 0x1e84622, 0x1e84629, 0x1e84646, (0x1e8463c, '498d77')),
        ('value', 0x1e8465d, 0x1e84664, 0x1e84684, (0x1e84677, '4983c7')),
    ]
    result = []
    for group, lea, length, child, source in specs:
        pointer, name = named_literal(image, lea, length)
        offset = 0
        if source is not None:
            site, prefix = source
            raw = image.read(site, 4)
            require(raw[:3] == bytes.fromhex(prefix), 'unexpected source-offset instruction')
            offset = raw[3]
        result.append({'group': group, 'name': name, 'name_va': pointer, 'name_site': lea,
                       'length_site': length, 'source_offset': offset,
                       'child_site': child, 'child': rel32_at(image, child)})
    for group, prefix in (('low', 'outer'), ('shared', 'outer'), ('json', 'outer'),
                          ('value', 'row')):
        require([r['name'] for r in result if r['group'] == group] ==
                [r['name'] for r in keys if r['group'] == prefix], 'reader/writer name mismatch')
    require([r['name'] for r in result if r['group'] == 'tracker'] ==
            ['name', 'hsc', 'i'], 'unexpected nested tracker names')
    for group in ('low', 'shared', 'json'):
        require([r['source_offset'] for r in result if r['group'] == group] == [0, 0x40, 0x58],
                'unexpected record layout')
    require([r['source_offset'] for r in result if r['group'] == 'tracker'] == [8, 0x18, 0x28],
            'unexpected tracker layout')
    require([r['source_offset'] for r in result if r['group'] == 'value'] == [0, 0x20, 0x38],
            'unexpected quorum value layout')
    return result


def transfer_rows(image):
    # Exact selected MOV forms, with displacement bytes decoded from the ELF.
    temporary = (
        (0x2ff3640, 0x2ff3678), (0x2ff3648, 0x2ff3670),
        (0x2ff3650, 0x2ff3668), (0x2ff3658, 0x2ff3660),
        (0x2ff3630, 0x2ff3638), (0x2ff3620, 0x2ff3628),
    )
    visitor = (
        (0x2ff3bb6, 0x2ff3bee), (0x2ff3bbe, 0x2ff3be6),
        (0x2ff3bc6, 0x2ff3bde), (0x2ff3bce, 0x2ff3bd6),
        (0x2ff3ba6, 0x2ff3bae), (0x2ff3b96, 0x2ff3b9e),
    )
    materializer = (
        (0x3752649, 0x3752670), (0x375264c, 0x3752668),
        (0x3752650, 0x3752660), (0x3752654, 0x3752658),
        (0x375263d, 0x3752641), (0x3752631, 0x3752635),
    )
    base_raw = image.read(0x3752134, 7)
    require(base_raw[:3] == bytes.fromhex('488d83'), 'wrong materializer source LEA')
    input_base = struct.unpack('<I', base_raw[3:])[0]

    def stack_displacement(site, load):
        raw = image.read(site, 8)
        if load:
            require(raw[:2] in (b'\x0f\x10', b'\x0f\x28') and
                    raw[2] in (0x84, 0x8c, 0x94, 0x9c) and raw[3] == 0x24,
                    'unexpected stack vector load')
        else:
            require(raw[:2] == b'\x0f\x29' and raw[2] in (0x84, 0x8c, 0x94, 0x9c)
                    and raw[3] == 0x24, 'unexpected stack vector store')
        return struct.unpack('<I', raw[4:])[0], (raw[2] >> 3) & 7

    def output_displacement(site):
        raw = image.read(site, 8)
        require(raw[:3] == b'\x41\x0f\x11' and raw[3] in (0x86, 0x8e, 0x96, 0x9e),
                'unexpected output vector store')
        return struct.unpack('<I', raw[4:])[0], (raw[3] >> 3) & 7

    result = []
    for src, dst in temporary:
        a, source_reg = stack_displacement(src, True)
        b, target_reg = stack_displacement(dst, False)
        require(source_reg == target_reg, 'local copy register mismatch')
        result.append(('local', src, dst, a, b, 16))
    for src, dst in visitor:
        a, source_reg = stack_displacement(src, True)
        b, target_reg = output_displacement(dst)
        require(source_reg == target_reg, 'visitor copy register mismatch')
        result.append(('visitor', src, dst, a, b, 16))
    for src, dst in materializer:
        raw = image.read(src, 4)
        if raw[:3] == bytes.fromhex('0f1000'):
            displacement = 0
        else:
            require(raw[:2] == bytes.fromhex('0f10') and raw[2] in (0x40, 0x48, 0x50, 0x58),
                    'unexpected materializer load')
            displacement = raw[3]
        source_reg = (raw[2] >> 3) & 7
        target_offset, target_reg = output_displacement(dst)
        require(source_reg == target_reg, 'materializer copy register mismatch')
        result.append(('materializer', src, dst, input_base + displacement, target_offset, 16))

    for row in result[:6]:
        require(row[4] - row[3] == 0x130, 'local transfer discontinuity')
    for row in result[6:12]:
        require(row[3] - row[4] == 0x670, 'visitor transfer discontinuity')
    for row in result[12:]:
        require(row[4] - row[3] == 0x1b20, 'materializer transfer discontinuity')
    require([r[3] for r in result[:6]] == [0x1fd0 + 16*i for i in range(6)],
            'local transfer does not cover six lanes')
    require([r[4] for r in result[6:12]] == [input_base + 16*i for i in range(6)],
            'visitor transfer does not cover input field')
    require([r[3] for r in result[12:]] == [input_base + 16*i for i in range(6)],
            'materializer transfer does not cover input field')
    return result


def decode_tables(image):
    slots = {0x56bded0: 0x1e64890, 0x5744b80: 0x489f3d0,
             0x5770e30: 0x3a054e0}
    relocations = relative_relocations(image, slots)
    rows = []
    for lane, base, vtable, expected_body, expected_writer in (
        ('low', 0x56bda38, 0x56bdeb8, 0x281a9c0, 0x1e84d50),
        ('shared', 0x57446e8, 0x5744b68, 0x4ae3770, 0x48c8ba0),
    ):
        require(vtable >= base and (vtable - base) % 0x20 == 0, 'unaligned descriptor row')
        index = (vtable - base) // 0x20
        require(index == 36, 'wrong descriptor row')
        slot = vtable + 0x18
        rel = next(r for r in relocations if r['slot'] == slot)
        size, align = struct.unpack('<QQ', image.read(vtable + 8, 16))
        require((size, align) == (8, 8), 'unexpected descriptor size or alignment')
        thunk = rel['addend']
        thunk_raw = image.read(thunk, 14)
        require(thunk_raw[:5] == bytes.fromhex('534889fbe8') and
                thunk_raw[9:] == bytes.fromhex('4889d85bc3'), 'unexpected thunk')
        body = thunk + 9 + struct.unpack('<i', thunk_raw[5:9])[0]
        require(body == expected_body, 'wrong hash closure target')
        writer_site = 0x281aa10 if lane == 'low' else 0x4ae37c0
        require(rel32_at(image, writer_site) == expected_writer, 'wrong row writer')
        rows.append({'lane': lane, 'row': index, 'table': vtable, 'slot': slot,
                     'size': size, 'alignment': align, 'thunk': thunk,
                     'thunk_raw': thunk_raw.hex(), 'closure': body,
                     'writer_site': writer_site, 'writer': expected_writer})
    return rows, relocations


def low_hash_capture(image, tables):
    # Prior builder snippets pass its second argument through a saved stack
    # slot to rbp. The selected box is later paired with a descriptor in r15.
    checked(image, 0x2755dfe, '4989f4')
    saved = checked(image, 0x2755f97, '4c89a42408020000')
    reloaded = checked(image, 0x27561c7, '488bac2408020000')
    save_offset = struct.unpack('<I', saved[4:])[0]
    require(save_offset == struct.unpack('<I', reloaded[4:])[0],
            'builder argument stack slot changed')
    box = checked(image, 0x2756938, '4989c7488d85b0350000498907')
    pair = checked(image, 0x2756f48, '4c89bb40020000488d0d626ff60248898b48020000')
    state_offset = struct.unpack('<I', box[6:10])[0]
    box_slot = struct.unpack('<I', pair[3:7])[0]
    vtable = 0x2756f56 + struct.unpack('<i', pair[10:14])[0]
    vtable_slot = struct.unpack('<I', pair[17:21])[0]
    row = next(r for r in tables if r['lane'] == 'low')
    require(state_offset == 0x35b0 and vtable == row['table'] and
            vtable_slot == box_slot + 8 and box_slot // 16 == row['row'] and
            box_slot % 16 == 0, 'hash capture does not match low descriptor')
    return state_offset, box_slot, vtable_slot, vtable, save_offset


def hash_writer_configs(image):
    """Decode the selected prior closures' local writer configuration."""
    rows = []
    for lane, site in (('low', 0x281a9f5), ('shared', 0x4ae37a5)):
        raw = checked(image, site, 'c744240800040001c644240c00')
        word = struct.unpack('<I', raw[4:8])[0]
        named, count_mode = raw[7], raw[12]
        require((named, count_mode) == (1, 0), 'changed hash writer configuration')
        rows.append((lane, site, raw.hex(), word, named, count_mode))
    return rows


def output_wrappers(image):
    """Bind the existing state writers to the new field-specific writers."""
    specs = (
        ('binary', 0x275b757, '498d96', 0x275b764, 0x27b29c0,
         0x27b29d1, 0x27b29d8, 0x1e84d50),
        ('json', 0x275c153, '488db3', 0x275c15d, 0x27af200,
         0x27af214, 0x27af21b, 0x1e84ee0),
    )
    rows = []
    for group, lea_site, prefix, call_site, wrapper, name_site, length_site, writer in specs:
        lea = image.read(lea_site, 7)
        require(lea[:3] == bytes.fromhex(prefix), 'changed state-field address')
        offset = struct.unpack('<I', lea[3:])[0]
        require(offset == 0x35b0 and rel32_at(image, call_site) == wrapper,
                'changed field wrapper call')
        literal_va, name = named_literal(image, name_site, length_site)
        require(name == 'lhvt', 'changed enclosing field name')
        if group == 'binary':
            jump_site = 0x27b29fc
            raw = checked(image, jump_site, 'e94f236dff')
            actual_writer = jump_site + len(raw) + struct.unpack('<i', raw[1:])[0]
        else:
            actual_writer = rel32_at(image, 0x27af25a)
        require(actual_writer == writer, 'changed field writer destination')
        rows.append((group, lea_site, offset, call_site, wrapper, literal_va, name, writer))
    # The text writer's opening and closing bytes on its selected normal path.
    checked(image, 0x1e84f1e, 'c604017b')
    checked(image, 0x1e850b8, 'c604307d')
    return rows


def default_path(image, relocations):
    """Decode the absent-field initializer's selected stores and indirect calls."""
    # A sentinel in the prior visitor selects this path. This is a boundary
    # observation; the visitor itself is not a newly attributed function.
    checked(image, 0x2ff35fc, '48b8000000000000008048398424d01f00007510')
    checked(image, 0x2ff3610, '488dbc2400210000')
    checked(image, 0x2ff361e, 'eb60')
    calls = []
    for label, site, expected, known_target in (
        ('absent_field_initializer', 0x2ff3618, 'ff1512d87702', 0x3a054e0),
        ('three_byte_allocation', 0x3a054ff, 'ff15d38ad601', None),
        ('allocation_failure_handler', 0x3a05566, 'ff154c8ad601', None),
    ):
        raw = checked(image, site, expected)
        slot = site + len(raw) + struct.unpack('<i', raw[2:])[0]
        if known_target is not None:
            rel = next((r for r in relocations if r['slot'] == slot), None)
            require(rel is not None and rel['addend'] == known_target,
                    'initializer relocation mismatch')
        calls.append((label, site, raw.hex(), slot, known_target))

    first_zero = checked(image, 0x3a054e8, '48c744240800000000')
    third_zero = checked(image, 0x3a054f1, '48c744241800000000')
    checked(image, 0x3a054fa, 'bf03000000')
    checked(image, 0x3a05505, '4885c07452')
    tail = checked(image, 0x3a0550a, 'c6400276')
    head = checked(image, 0x3a0550e, '66c7006c68')
    require(tail[2] == len(head[3:]), 'name byte stores do not meet')
    literal = head[3:] + tail[3:]
    require(len(literal) == image.read(0x3a054fa, 5)[1] and literal == b'lhv',
            'unexpected default name')
    checked(image, 0x3a05513, '488b4c241848894b38')
    copied = checked(image, 0x3a0551c, '0f104424080f114328')
    zeroed = checked(image, 0x3a05540, '0f57c00f114318')
    checked(image, 0x3a0554f, '0f114350')
    checked(image, 0x3a0555c, 'bf01000000be03000000')
    checked(image, 0x3a0556c, '0f0b')

    rows = []
    for name, site, raw_hex, offset_index in (
        ('tracker_name_word0', 0x3a05525, '48c70303000000', None),
        ('tracker_name_length', 0x3a05530, '48c7431003000000', 3),
        ('quorum_word0', 0x3a05538, '48c7434000000000', 3),
        ('quorum_word1', 0x3a05547, '48c7434808000000', 3),
    ):
        raw = checked(image, site, raw_hex)
        offset = 0 if offset_index is None else raw[offset_index]
        value = struct.unpack('<I', raw[-4:])[0]
        rows.append((name, offset, 8, str(value), site))
    ptr = checked(image, 0x3a0552c, '48894308')
    rows.append(('tracker_name_pointer', ptr[-1], 8, 'allocation_result', 0x3a0552c))
    # Only the first and third source words of the 24-byte temporary are set
    # here. Its middle word is copied but is not established by these bytes.
    require(first_zero[4] == copied[4] and third_zero[4] == copied[4] + 16,
            'unexpected stack source offsets')
    require(first_zero[-4:] == third_zero[-4:] == bytes(4), 'stack words are not zero')
    base = copied[-1]
    rows.extend((
        ('tracker_i_word0', base, 8, '0', 0x3a05521),
        ('tracker_i_word1', base + 8, 8, 'unspecified_stack_word', 0x3a05521),
        ('tracker_i_word2', base + 16, 8, '0', 0x3a05518),
    ))
    hsc = zeroed[-1]
    quorum_tail = image.read(0x3a0554f, 4)[-1]
    rows.extend((
        ('tracker_hsc_word0', hsc, 8, '0', 0x3a05543),
        ('tracker_hsc_word1', hsc + 8, 8, '0', 0x3a05543),
        ('quorum_word2', quorum_tail, 8, '0', 0x3a0554f),
        ('highest_quorum_height', quorum_tail + 8, 8, '0', 0x3a0554f),
    ))
    rows.sort(key=lambda row: row[1])
    require([r[1] for r in rows] == list(range(0, 0x60, 8)),
            'default stores do not cover the selected 96 bytes')
    return literal, rows, calls


def stride_cases(image):
    specs = (
        ('json_collect_stride', 0x340f7c5, '486bcb'),
        ('json_cleanup_stride', 0x308d333, '486bf5'),
        ('low_writer_stride', 0x1e43c40, '496bc6'),
        ('shared_writer_stride', 0x440a9b0, '496bc6'),
        ('low_writer_advance', 0x1e43c8c, '4983c7'),
        ('shared_writer_advance', 0x440a9fc, '4983c7'),
    )
    rows = []
    for label, site, prefix in specs:
        data = image.read(site, 4)
        require(data[:3] == bytes.fromhex(prefix), 'unexpected stride instruction')
        rows.append((label, site, data.hex(), data[3]))
    require({r[3] for r in rows} == {0x58}, 'row strides disagree')
    # The list writer shifts the count by this many bits before its high-word test.
    raw = image.read(0x1e43ab1, 7)
    require(raw[:3] == bytes.fromhex('4c89f0') and raw[3:6] == bytes.fromhex('48c1e8'),
            'unexpected count high-word test')
    return rows, raw[6]


def marker_cases(image):
    code = image.read(0x1e84a6f, 12)
    require(code[:3] == bytes.fromhex('4080f5') and code[4:7] == bytes.fromhex('40c0e5')
            and code[8:11] == bytes.fromhex('4080cd'), 'unexpected marker operations')
    xor_value, shift, or_value = code[3], code[7], code[11]
    return [(mode, ((mode ^ xor_value) << shift | or_value) & 255) for mode in (0, 1)]


def tsv(header, rows):
    f = io.StringIO(newline='')
    w = csv.writer(f, delimiter='\t', lineterminator='\n')
    w.writerow(header)
    w.writerows(rows)
    return f.getvalue().encode('utf-8')


def hx(value):
    return '' if value is None else hex(value)


def collect(data):
    authenticate(data)
    image = Image(data)
    fdes = selected_fdes(image)
    for label, start, raw in WINDOW_PINS:
        checked(image, start, raw)
    branches = [(site, raw, *branch(image, site, raw, target))
                for site, raw, target in BRANCH_PINS]
    calls = [(site, raw, call(image, site, raw, target)) for site, raw, target in CALL_PINS]
    keys = decode_keys(image)
    tracker_keys, tracker_tables = tracker_dispatch(image)
    hsc_fields = hsc_dispatch(image)
    diagnostics = diagnostic_links(image)
    templates = diagnostic_templates(image)
    writers = writer_fields(image, keys)
    transfers = transfer_rows(image)
    tables, relocations = decode_tables(image)
    capture = low_hash_capture(image, tables)
    configs = hash_writer_configs(image)
    wrappers = output_wrappers(image)
    default_name, default_rows, indirect_calls = default_path(image, relocations)
    strides, count_shift = stride_cases(image)
    markers = marker_cases(image)

    headers, sites = [], []
    for f in fdes:
        header, rows = lsda_rows(image, f)
        if header is not None:
            headers.append((f, header))
            sites.extend((f, r) for r in rows)
    associations = []
    for site, raw, target in calls:
        owner = next((f for f in fdes if f['start'] <= site < f['end']), None)
        if owner is None or owner['lsda'] is None:
            continue
        covered = [r for f, r in sites if f['start'] == owner['start']
                   and r['start'] <= site + 4 < r['end']]
        require(len(covered) <= 1, 'overlapping LSDA call-site rows')
        if covered:
            associations.append((site, target, owner, covered[0]))

    output = {}
    output['functions.tsv'] = tsv(
        ['start_va', 'end_va_exclusive', 'file_offset', 'fde_va', 'cie_va',
         'lsda_va', 'unwind_index', 'body_sha256', 'body_hex'],
        [(hx(f['start']), hx(f['end']), hx(f['file_offset']), hx(f['fde']), hx(f['cie']),
          hx(f['lsda']), f['index'], f['sha256'], f['raw']) for f in fdes])
    output['windows.tsv'] = tsv(
        ['label', 'start_va', 'end_va_exclusive', 'file_offset', 'bytes_hex'],
        [(name, hx(start), hx(start + len(bytes.fromhex(raw))),
          hx(image.offset(start, len(bytes.fromhex(raw)))), raw)
         for name, start, raw in WINDOW_PINS])
    output['branches.tsv'] = tsv(
        ['site_va', 'file_offset', 'bytes_hex', 'condition_code', 'fallthrough_va', 'taken_va'],
        [(hx(site), hx(image.offset(site, len(bytes.fromhex(raw)))), raw, hex(cond),
          hx(fall), hx(target)) for site, raw, cond, fall, target in branches])
    output['calls.tsv'] = tsv(
        ['site_va', 'file_offset', 'bytes_hex', 'target_va', 'selected_target'],
        [(hx(site), hx(image.offset(site, 5)), raw, hx(target),
          'yes' if any(f['start'] == target for f in fdes) else 'boundary')
         for site, raw, target in calls])
    output['keys.tsv'] = tsv(
        ['group', 'name', 'length', 'length_site', 'duplicate_guard', 'duplicate_target',
         'fragment_instruction', 'fragment_va', 'key_offset', 'fragment_hex'],
        [(k['group'], k['name'], k['length'], hx(k['length_site']),
          hx(k['duplicate_guard']), hx(k['duplicate_target']), hx(p['instruction']),
          hx(p['data_va']), p['offset'], p['bytes']) for k in keys for p in k['pieces']])
    output['fields.tsv'] = tsv(
        ['group', 'name', 'name_va', 'name_instruction', 'length_instruction',
         'source_offset', 'child_call', 'child_target'],
        [(r['group'], r['name'], hx(r['name_va']), hx(r['name_site']), hx(r['length_site']),
          hx(r['source_offset']), hx(r['child_site']), hx(r['child'])) for r in writers])
    output['tracker-keys.tsv'] = tsv(
        ['tag', 'name', 'first_arm_va', 'after_i_arm_va',
         'duplicate_before_i_va', 'duplicate_after_i_va'],
        [(tag, name, hx(first), hx(after), hx(dup_before), hx(dup_after))
         for tag, name, first, after, dup_before, dup_after in tracker_keys])
    output['tracker-tables.tsv'] = tsv(
        ['base_va', 'table_hex', 'tag_0', 'tag_1', 'tag_2', 'tag_3', 'tag_4'],
        [(hx(base), raw, *(hx(target) for target in targets))
         for base, raw, targets in tracker_tables])
    output['tracker-cases.tsv'] = tsv(
        ['presence_mask_name_hsc_i', 'selected_completion', 'hsc_word_policy'],
        tracker_presence_cases())
    output['hsc-fields.tsv'] = tsv(
        ['name', 'payload_offset', 'child_call_va', 'child_va', 'duplicate_branch_va',
         'duplicate_target_va', 'missing_branch_va', 'missing_target_va'],
        [(name, hx(offset), hx(site), hx(child), hx(dup_site), hx(dup), hx(miss_site), hx(miss))
         for name, offset, site, child, dup_site, dup, miss_site, miss in hsc_fields])
    output['hsc-cases.tsv'] = tsv(
        ['presence_mask_q_i', 'selected_completion'], hsc_presence_cases())
    output['diagnostics.tsv'] = tsv(
        ['role', 'lea_va', 'literal_va', 'name'],
        [(role, hx(site), hx(address), name) for role, site, address, name in diagnostics])
    output['diagnostic-templates.tsv'] = tsv(
        ['role', 'lea_va', 'descriptor_va', 'descriptor_hex', 'prefix'],
        [(role, hx(site), hx(address), raw, prefix)
         for role, site, address, raw, prefix in templates])
    output['transfers.tsv'] = tsv(
        ['stage', 'load_va', 'store_va', 'source_offset', 'destination_offset', 'width_bytes'],
        [(name, hx(src), hx(dst), hx(a), hx(b), width)
         for name, src, dst, a, b, width in transfers])
    output['descriptors.tsv'] = tsv(
        ['lane', 'row_zero_based', 'vtable_va', 'call_slot_va', 'box_size', 'box_alignment',
         'thunk_va', 'thunk_hex', 'prior_closure_va', 'writer_call_va', 'writer_va'],
        [(r['lane'], r['row'], hx(r['table']), hx(r['slot']), r['size'], r['alignment'],
          hx(r['thunk']), r['thunk_raw'], hx(r['closure']), hx(r['writer_site']), hx(r['writer']))
         for r in tables])
    output['low-capture.tsv'] = tsv(
        ['capture_instruction_va', 'pair_instruction_va', 'state_offset',
         'box_array_offset', 'vtable_array_offset', 'vtable_va', 'argument_stack_offset'],
        [(hx(0x2756938), hx(0x2756f48), *(hx(value) for value in capture))])
    output['hash-configs.tsv'] = tsv(
        ['lane', 'store_va', 'bytes_hex', 'word_at_offset_8', 'byte_at_offset_b',
         'byte_at_offset_c'],
        [(lane, hx(site), raw, hx(word), named, count_mode)
         for lane, site, raw, word, named, count_mode in configs])
    output['output-wrappers.tsv'] = tsv(
        ['format', 'state_lea_va', 'state_offset', 'prior_call_va', 'wrapper_va',
         'name_va', 'name', 'writer_va'],
        [(group, hx(lea), hx(offset), hx(site), hx(wrapper), hx(name_va), name, hx(writer))
         for group, lea, offset, site, wrapper, name_va, name, writer in wrappers])
    output['relocations.tsv'] = tsv(
        ['slot_va', 'rela_file_offset', 'r_info', 'addend', 'entry_hex'],
        [(hx(r['slot']), hx(r['entry_offset']), hx(r['info']), hx(r['addend']), r['raw'])
         for r in relocations])
    output['default-layout.tsv'] = tsv(
        ['word', 'offset', 'width_bytes', 'value', 'store_va'],
        [(name, hx(offset), width, value, hx(site))
         for name, offset, width, value, site in default_rows])
    output['default-calls.tsv'] = tsv(
        ['role', 'call_va', 'instruction_hex', 'slot_va', 'resolved_addend'],
        [(name, hx(site), raw, hx(slot), hx(target))
         for name, site, raw, slot, target in indirect_calls])
    output['default-name.tsv'] = tsv(
        ['name', 'ascii_hex', 'length'],
        [(default_name.decode('ascii'), default_name.hex(), len(default_name))])
    output['strides.tsv'] = tsv(
        ['label', 'instruction_va', 'instruction_hex', 'stride'],
        [(label, hx(site), raw, value) for label, site, raw, value in strides])
    output['lsda-headers.tsv'] = tsv(
        ['fde_start', 'lsda_va', 'file_offset', 'type_encoding', 'type_offset',
         'header_hex', 'callsite_table_size'],
        [(hx(f['start']), hx(h['address']), hx(h['offset']), hx(h['ttype']),
          hx(h['type_offset']), h['header'], h['table_size']) for f, h in headers])
    output['lsda-rows.tsv'] = tsv(
        ['fde_start', 'range_start', 'range_end_exclusive', 'landing_va', 'action', 'row_hex'],
        [(hx(f['start']), hx(r['start']), hx(r['end']), hx(r['landing']), r['action'], r['raw'])
         for f, r in sites])
    output['lsda-calls.tsv'] = tsv(
        ['call_va', 'target_va', 'fde_start', 'range_start', 'range_end_exclusive',
         'landing_va', 'action'],
        [(hx(site), hx(target), hx(f['start']), hx(r['start']), hx(r['end']),
          hx(r['landing']), r['action']) for site, target, f, r in associations])

    case_rows = []
    for group in ('outer', 'row'):
        names = [k['name'] for k in keys if k['group'] == group]
        for mask in range(1 << len(names)):
            missing = next((n for i, n in enumerate(names) if not mask & (1 << i)), '')
            case_rows.append((group, 'presence', mask, '', 'missing:' + missing if missing else 'complete'))
        for k in (r for r in keys if r['group'] == group):
            case_rows.append((group, 'repeated', '', k['name'], hx(k['duplicate_target'])))
    output['cases.tsv'] = tsv(['group', 'case', 'presence_mask', 'key', 'result'], case_rows)
    output['marker-cases.tsv'] = tsv(['mode_byte', 'selected_header_byte'],
                                     [(m, hx(v)) for m, v in markers])
    count_rows = [(n, n >> count_shift, 'large' if n >> count_shift else 'bounded')
                  for n in (0, 1, (1 << count_shift) - 1, 1 << count_shift,
                            (1 << 64) - 1)]
    output['count-cases.tsv'] = tsv(['input_count', 'high_word', 'selected_count_class'], count_rows)
    summary = {
        'target_sha256': SHA256,
        'selected_fdes': len(fdes),
        'selected_windows': len(WINDOW_PINS),
        'selected_branches': len(branches),
        'selected_direct_calls': len(calls),
        'selected_key_names': len(keys),
        'tracker_key_names': len(tracker_keys),
        'tracker_dispatch_tables': len(tracker_tables),
        'hsc_key_names': len(hsc_fields),
        'diagnostic_names': len(diagnostics),
        'diagnostic_templates': len(templates),
        'key_fragments': sum(len(k['pieces']) for k in keys),
        'writer_fields': len(writers),
        'copy_lanes': len(transfers),
        'descriptor_rows': len(tables),
        'hash_writer_configs': len(configs),
        'relative_relocations': len(relocations),
        'default_words': len(default_rows),
        'default_indirect_calls': len(indirect_calls),
        'output_wrappers': len(wrappers),
        'lsda_headers': len(headers),
        'lsda_rows': len(sites),
        'selected_callsite_associations': len(associations),
        'case_rows': len(case_rows),
        'marker_cases': len(markers),
        'count_cases': len(count_rows),
        'limitations': 'Selected static evidence, not a complete call graph or a runtime trace.',
    }
    output['summary.json'] = (json.dumps(summary, indent=2, sort_keys=True) + '\n').encode()
    return output


def generate(binary, out):
    with binary.open('rb') as handle:
        with mmap.mmap(handle.fileno(), 0, access=mmap.ACCESS_READ) as data:
            files = collect(data)
    out.mkdir(parents=True, exist_ok=True)
    for name, contents in sorted(files.items()):
        (out / name).write_bytes(contents)
    return files


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', required=True, type=Path)
    args = parser.parse_args()
    generate(TARGET, args.out)


if __name__ == '__main__':
    try:
        main()
    except (EvidenceError, ValueError, OSError, struct.error) as exc:
        print('abci_l1_quorum94: ' + str(exc), file=sys.stderr)
        sys.exit(1)
